window.__votdWeek && window.__votdWeek({"week":"2029-10-22","reading":"Doctrine and Covenants 121–123","days":[{"d":"2029-10-22","ref":"D&C 121:28","b":"D&C","c":121,"v":28,"he":"עֵת תָּבוֹא בָּהּ לֹא יִמָּנַע דָּבָר אִם אֵל אֶחָד וְאִם אֱלֹהִים רַבִּים יִגָּלוּ׃","en":"A time to come in the which nothing shall be withheld, whether there be one God or many gods, they shall be manifest."},{"d":"2029-10-23","ref":"D&C 121:41","b":"D&C","c":121,"v":41,"he":"אֵין כֹּחַ אוֹ מֶמְשָׁלָה יְכוֹלִים אוֹ רְאוּיִים לָקוּם בִּזְכוּת הַכְּהֻנָּה כִּי־אִם בְּפִתּוּי בְּאֶרֶךְ אַפַּיִם בְּנַחַת וְעַנְוָה וּבְאַהֲבָה בְּלֹא־חֲנֻפָּה׃","en":"No power or influence can or ought to be maintained by virtue of the priesthood, only by persuasion, by long-suffering, by gentleness and meekness, and by love unfeigned;"},{"d":"2029-10-24","ref":"D&C 121:42","b":"D&C","c":121,"v":42,"he":"בְּחֶסֶד וּבְדַעַת טְהוֹרָה אֲשֶׁר תַּרְחִיב אֶת־הַנֶּפֶשׁ מְאֹד בְּלֹא חֹנֶף וּבְלֹא רְמִיָּה׃","en":"By kindness, and pure knowledge, which shall greatly enlarge the soul without hypocrisy, and without guile—"},{"d":"2029-10-25","ref":"D&C 122:2","b":"D&C","c":122,"v":2,"he":"וּבָרֵי לֵבָב וַחֲכָמִים וּנְדִיבִים וּטְהוֹרִים יְבַקְשׁוּ עֵצָה וּרְשׁוּת וּבְרָכוֹת תָּמִיד מִתַּחַת יָדֶךָ׃","en":"While the pure in heart, and the wise, and the noble, and the virtuous, shall seek counsel, and authority, and blessings constantly from under thy hand."},{"d":"2029-10-26","ref":"D&C 122:5","b":"D&C","c":122,"v":5,"he":"אִם נִקְרֵאתָ לַעֲבֹר בְּצָרָה אִם אַתָּה בְּסַכָּנוֹת בֵּין אֲחֵי שָׁקֶר אִם אַתָּה בְּסַכָּנוֹת בֵּין שׁוֹדְדִים אִם בְּסַכָּנוֹת בַּיַּבָּשָׁה אוֹ בַּיָּם׃","en":"If thou art called to pass through tribulation; if thou art in perils among false brethren; if thou art in perils among robbers; if thou art in perils by land or by sea;"},{"d":"2029-10-27","ref":"D&C 122:8","b":"D&C","c":122,"v":8,"he":"בֶּן־הָאָדָם יָרַד מִתַּחַת לְכֻלָּם הַגָּדוֹל אַתָּה מִמֶּנּוּ׃","en":"The Son of Man hath descended below them all. Art thou greater than he?"},{"d":"2029-10-28","ref":"D&C 123:16","b":"D&C","c":123,"v":16,"he":"יְדַעְתֶּם אַחַי כִּי אֳנִיָּה גְּדוֹלָה מְאֹד נֶעֱזֶרֶת מְאֹד מְאֹד מִמָּשׁוֹט קָטֹן מְאֹד בְּעֵת סַעַר בְּהִשָּׁמְרָהּ נֹכַח הָרוּחַ וְהַגַּלִּים׃","en":"You know, brethren, that a very large ship is benefited very much by a very small helm in the time of a storm, by being kept workways with the wind and the waves."}]});
